export type SendChatMessageMutationResult = NonNullable<
  Awaited<ReturnType<typeof sendChatMessage>>
>;
export type SendChatMessageMutationBody = BodyType<SendChatBody>;
export type SendChatMessageMutationError = ErrorType<unknown>;

/**
 * @summary Ask a question about the session's documents (RAG)
 */
export const useSendChatMessage = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof sendChatMessage>>,
    TError,
    { sessionId: number; data: BodyType<SendChatBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof sendChatMessage>>,
  TError,
  { sessionId: number; data: BodyType<SendChatBody> },
  TContext
> => {
  return useMutation(getSendChatMessageMutationOptions(options));
};

/**
 * @summary Get chat history for a session
 */
export const getListMessagesUrl = (sessionId: number) => {
  return `/api/ai/sessions/${sessionId}/messages`;
};

export const listMessages = async (
  sessionId: number,
  options?: RequestInit,
): Promise<ChatMessage[]> => {
  return customFetch<ChatMessage[]>(getListMessagesUrl(sessionId), {
    ...options,
    method: "GET",
  });
};

export const getListMessagesQueryKey = (sessionId: number) => {
  return [`/api/ai/sessions/${sessionId}/messages`] as const;
};

export const getListMessagesQueryOptions = <
  TData = Awaited<ReturnType<typeof listMessages>>,
  TError = ErrorType<unknown>,
>(
  sessionId: number,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listMessages>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getListMessagesQueryKey(sessionId);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof listMessages>>> = ({
    signal,
  }) => listMessages(sessionId, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!sessionId,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof listMessages>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type ListMessagesQueryResult = NonNullable<
  Awaited<ReturnType<typeof listMessages>>
>;
export type ListMessagesQueryError = ErrorType<unknown>;

/**
 * @summary Get chat history for a session
 */

export function useListMessages<
  TData = Awaited<ReturnType<typeof listMessages>>,
  TError = ErrorType<unknown>,
>(
  sessionId: number,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listMessages>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getListMessagesQueryOptions(sessionId, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
